import React, { memo } from "react";
import Badge from "@mui/material/Badge";
import ListItem from "@mui/material/ListItem";
import ListItemButton from "@mui/material/ListItemButton";
import ListItemIcon from "@mui/material/ListItemIcon";
import ListItemText from "@mui/material/ListItemText";
import Tooltip from "@mui/material/Tooltip";
import Typography from "@mui/material/Typography";

import type { Page } from "../../ui/Router";

export interface ICreateProps {
  key_: Page;
  icon: React.ReactElement["type"];
  count?: number;
  active?: boolean;
  alternateKeys?: Page[];
}

export interface SidebarItemProps extends ICreateProps {
  clickFn: () => void;
  flash: boolean;
  classes: Record<"listitem" | "active", string>;
  sidebarOpen: boolean;
}

export const SidebarItem = memo(function SidebarItem(props: SidebarItemProps): React.ReactElement {
  const color = props.flash ? "error" : props.active ? "primary" : "secondary";
  const labels: Record<string, string> = {
    "Active Scripts": "Scripts activos",
    "Script Editor": "Editor de scripts",
    "Create Program": "Crear programa",
    "Recently Killed Scripts": "Scripts detenidos",
    "Recent Errors": "Errores recientes",
    Stats: "Estadísticas",
    Factions: "Facciones",
    Augmentations: "Augmentations",
    Hacknet: "Hacknet",
    Sleeves: "Sleeves",
    Grafting: "Grafting",
    City: "Ciudad",
    Travel: "Viajar",
    Job: "Trabajo",
    "Stock Market": "Bolsa",
    Corporation: "Corporación",
    Gang: "Banda",
    Milestones: "Objetivos",
    Documentation: "Documentación",
    Achievements: "Logros",
    Options: "Opciones",
  };
  const label = labels[props.key_] ?? props.key_;
  return (
    <ListItem
      classes={{ root: props.classes.listitem }}
      key={props.key_}
      className={props.active ? props.classes.active : ""}
      disablePadding
    >
      <ListItemButton onClick={props.clickFn}>
        <ListItemIcon>
          <Badge badgeContent={(props.count ?? 0) > 0 ? props.count : undefined} color="error">
            <Tooltip title={!props.sidebarOpen ? label : ""}>
              <props.icon color={color} />
            </Tooltip>
          </Badge>
        </ListItemIcon>
        <ListItemText>
          <Typography color={color}>{label}</Typography>
        </ListItemText>
      </ListItemButton>
    </ListItem>
  );
});
