import { Terminal } from "../../Terminal";
import { BaseServer } from "../../Server/BaseServer";

export function sudov(args: (string | number | boolean)[], server: BaseServer): undefined {
  if (args.length !== 0) {
    Terminal.error("Cantidad de argumentos incorrecta. Uso: sudov");
    return;
  }

  if (server.hasAdminRights) {
    Terminal.print("Tienes acceso ROOT a esta máquina");
  } else {
    Terminal.print("NO tienes acceso root a esta máquina");
  }
}
