import { Terminal } from "../../Terminal";
import { parseAliasDeclaration, printAliases } from "../../Alias";

export function alias(args: (string | number | boolean)[]): undefined {
  if (args.length === 0) {
    printAliases();
    return;
  }
  if (args[0] === "--all") {
    Terminal.error(`--all está reservado para eliminar`);
    return;
  }
  if (args.length === 1) {
    if (parseAliasDeclaration(args[0] + "")) {
      Terminal.print(`Alias ${args[0]} creado`);
      return;
    }
  }
  if (args.length === 2) {
    if (args[0] === "-g") {
      if (parseAliasDeclaration(args[1] + "", true)) {
        Terminal.print(`Alias global ${args[1]} creado`);
        return;
      }
    }
  }
  Terminal.error('Incorrect usage of alias command. Usage: alias [-g] [aliasname="value"]');
}
