import { Terminal } from "../../Terminal";
import type { TerminalAction } from "../TerminalAction";
import { Player } from "@player";
import { BaseServer } from "../../Server/BaseServer";
import { HacknetServer } from "../../Hacknet/HacknetServer";
import { Server } from "../../Server/Server";
import { DarknetServer } from "../../Server/DarknetServer";
import { Page } from "../../ui/Router";
import { Router } from "../../ui/GameRoot";
import { Engine } from "../../engine";
import { SpecialServers } from "../../Server/data/SpecialServers";
import { calculateHackingTime } from "../../Hacking";

export function backdoor(args: (string | number | boolean)[], server: BaseServer): undefined | TerminalAction {
  if (args.length !== 0) {
    Terminal.error("Uso incorrecto del comando backdoor. Uso: backdoor");
    return;
  }

  if (!(server instanceof Server) && !(server instanceof DarknetServer)) {
    Terminal.error("Solo se puede instalar una puerta trasera (backdoor) en servidores normales");
    return;
  }
  if (server.purchasedByPlayer) {
    Terminal.error(
      "Cannot instala una `backdoor` on your own machines! You are currently connected to your home PC or one of your cloud servers.",
    );
    return;
  }
  if (!server.hasAdminRights) {
    Terminal.error("¡No tienes permisos de administrador en esta máquina!");
    return;
  }
  if (server.requiredHackingSkill && server.requiredHackingSkill > Player.skills.hacking) {
    Terminal.error(
      "Your hacking skill is not high enough to instala una `backdoor` on this machine. Try analyzing the machine to determine the required hacking skill.",
    );
    return;
  }

  if (server.backdoorInstalled) {
    Terminal.warn(
      `You have already installed a backdoor on this server. You can check the "Backdoor" status via the "analyze" command.`,
    );
  }

  // Backdoor should take the same amount of time as hack
  if (server instanceof HacknetServer) {
    Terminal.error("No se puede instalar una puerta trasera en este tipo de servidor");
    return;
  }
  if (!(server instanceof Server || server instanceof DarknetServer)) {
    throw new Error("server should be normal server");
  }
  return Terminal.timedAction(calculateHackingTime(server, Player) / 4, "backdoor", () => {
    server.backdoorInstalled = true;
    if (SpecialServers.WorldDaemon === server.hostname) {
      if (Player.bitNodeN == null) {
        Player.bitNodeN = 1;
      }
      Router.toPage(Page.BitVerse, { flume: false, quick: false });
      return;
    }
    // Manunally check for faction invites
    Engine.Counters.checkFactionInvitations = 0;
    Engine.checkCounters();

    Terminal.print(`¡Puerta trasera (backdoor) en '${server.hostname}' instalada con éxito!`);
  });
}
