import React, { useState } from "react";

import { TextField } from "@mui/material";
import Button from "@mui/material/Button";
import Paper from "@mui/material/Paper";
import Typography from "@mui/material/Typography";
import Tooltip from "@mui/material/Tooltip";
import InfoIcon from "@mui/icons-material/Info";

import { Player } from "@player";
import {
  calculateCurrentShareBonus,
  calculateShareBonusWithAdditionalThreads,
  pendingUIShareJobIds,
  ShareBonusTime,
  startSharing,
} from "../../NetworkShare/Share";
import { formatRam, formatNumber } from "../../ui/formatNumber";
import { dialogBoxCreate } from "../../ui/React/DialogBox";
import { useCycleRerender } from "../../ui/React/hooks";
import { roundToTwo } from "../../utils/helpers/roundToTwo";

export function ShareOption({ rerender }: { rerender: () => void }): React.ReactElement {
  const [ram, setRam] = useState<number>(0);
  useCycleRerender();

  const home = Player.getHomeComputer();
  const threads = Math.floor(ram / 4);
  const ramUsage = roundToTwo(4 * threads);

  function onShare(): void {
    if (threads === 0) {
      return;
    }
    if (!Number.isFinite(threads) || threads < 0) {
      dialogBoxCreate("La cantidad de RAM no es válida.");
      return;
    }
    const freeRAM = home.maxRam - home.ramUsed;
    if (ramUsage > freeRAM + 0.001) {
      dialogBoxCreate("No tienes suficiente RAM libre.");
      return;
    }

    home.updateRamUsed(roundToTwo(home.ramUsed + ramUsage));
    const end = startSharing(threads, home.cpuCores);
    const jobId = window.setTimeout(() => {
      end();
      if (pendingUIShareJobIds.includes(jobId)) {
        home.updateRamUsed(roundToTwo(home.ramUsed - ramUsage));
      }
      rerender();
    }, ShareBonusTime);
    pendingUIShareJobIds.push(jobId);
    rerender();
  }

  return (
    <Paper sx={{ my: 1, p: 1 }}>
      <Typography>
        Puedes compartir la RAM libre de home con tus facciones para ganar reputación más deprisa. Cada vez que la
        compartes, recibes una bonificación durante {ShareBonusTime / 1000} segundos. Después recuperas esa RAM. También
        puedes compartir la RAM de otros servidores donde tengas acceso de administrador mediante la API ns.share().
        <br />
        RAM libre en el ordenador home: {formatRam(home.maxRam - home.ramUsed)}.
        <br />
        Bonificación actual: {formatNumber(calculateCurrentShareBonus(), 6)}. Bonificación con {formatRam(ramUsage)}:{" "}
        {formatNumber(calculateShareBonusWithAdditionalThreads(threads, home.cpuCores), 6)}
      </Typography>

      <Typography component="div" style={{ display: "flex" }}>
        <TextField
          value={ram}
          onChange={(event) => {
            if (event.target.value === "") {
              setRam(0);
              return;
            }
            const value = Number.parseFloat(event.target.value);
            if (!Number.isFinite(value) || value < 0) {
              return;
            }
            setRam(value);
          }}
        />
        <Tooltip
          title={
            <Typography>
              La RAM compartida se redondea hacia abajo al múltiplo de 4 más cercano.
              <br />
              Por ejemplo, si eliges 18 GB, se compartirán 16 GB.
            </Typography>
          }
        >
          <Typography component="div" style={{ display: "flex", alignItems: "center" }}>
            <Button onClick={onShare}>Compartir</Button>
            <InfoIcon sx={{ fontSize: "1.5em", marginLeft: "10px" }} />
          </Typography>
        </Tooltip>
      </Typography>
    </Paper>
  );
}
