import { Terminal } from "../../Terminal";
import { removeAlias, Aliases, GlobalAliases } from "../../Alias";

export function unalias(args: (string | number | boolean)[]): undefined {
  if (args.length !== 1) {
    Terminal.error("Uso incorrecto del comando unalias. Uso: unalias [alias] o unalias --all");
    return;
  } else if (args[0] === "--all") {
    for (const alias of Aliases) {
      if (removeAlias(alias[0] + "")) {
        Terminal.print(`Alias ${alias[0]} eliminado`);
      }
    }
    for (const alias of GlobalAliases) {
      if (removeAlias(alias[0] + "")) {
        Terminal.print(`Alias ${alias[0]} eliminado`);
      }
    }
  } else if (removeAlias(args[0] + "")) {
    Terminal.print(`Alias ${args[0]} eliminado`);
  } else {
    Terminal.error(`No existe ese alias: ${args[0]}`);
  }
}
