import { Terminal } from "../../Terminal";
import { findRunningScripts } from "../../Script/ScriptHelpers";
import { killWorkerScriptByPid } from "../../Netscript/killWorkerScript";
import { hasScriptExtension } from "../../Paths/ScriptFilePath";

import type { BaseServer } from "../../Server/BaseServer";

export function kill(args: (string | number | boolean)[], server: BaseServer): undefined {
  try {
    if (args.length < 1 || typeof args[0] === "boolean") {
      Terminal.error("Uso incorrecto del comando kill. Uso: kill [pid] o kill [nombre_del_script] [arg1] [arg2]...");
      return;
    }

    // Kill by PID
    if (typeof args[0] === "number") {
      const pid = args[0];
      const res = killWorkerScriptByPid(pid);
      if (res) {
        Terminal.print(`Deteniendo el script con PID ${pid}`);
      } else {
        Terminal.error(`No se pudo detener el script con PID ${pid}. Ese script no se está ejecutando`);
      }

      return;
    }

    const path = Terminal.getFilepath(args[0]);
    if (!path) return Terminal.error(`Nombre de archivo no válido: ${args[0]}`);
    if (!hasScriptExtension(path))
      return Terminal.error(`Extensión de archivo no válida. Kill solo se puede usar con scripts.`);
    const runningScripts = findRunningScripts(path, args.slice(1), server);
    if (runningScripts === null) {
      Terminal.error("Ese script no se está ejecutando. No hay nada que detener");
      return;
    }
    let killed = 0;
    for (const pid of runningScripts.keys()) {
      killed++;
      if (killed < 5) {
        Terminal.print(`Deteniendo ${path} con pid ${pid}`);
      }
      killWorkerScriptByPid(pid);
    }
    if (killed >= 5) {
      Terminal.print(`... se detuvieron ${killed} instancias en total`);
    }
  } catch (error) {
    console.error(error);
    Terminal.error(String(error));
  }
}
